cat > /tmp/verify/verify10.js <<'EOF'
const { chromium } = require('playwright');
(async () => {
    const browser = await chromium.launch();
    const page = await browser.newPage();
    const net = [];
    page.on('response', async r => { if (r.url().includes('_search')) { let b=''; try { b=(await r.text()).replace(/\s+/g,' ').slice(0,140);} catch(e){} net.push(r.status() + ' ' + b); } });
    await page.goto('http://localhost/examples/spotify/indexSpotify.html', { waitUntil: 'networkidle' });
    await page.waitForTimeout(2500);
    await page.click('.oneCollapsibleItem.filter .collapsible-header');
    await page.waitForTimeout(500);
    await page.selectOption('#dataExplorerDataFields', 'artists.name');
    await page.waitForTimeout(1500);
    await page.click('.oneCollapsibleItem.output .collapsible-header');
    await page.waitForTimeout(500);
    const select = await page.$('#outputControls select');
    await select.selectOption('barChart');
    await page.waitForTimeout(1000);
    const dimSelect = await page.$('#outputControls select.dimension, #outputControls .dimension');
    if (dimSelect) {
        const opts = await dimSelect.evaluate(el => Array.from(el.options).slice(0,10).map(o=>o.value)).catch(e=>['ERR']);
        console.log('DIM_OPTIONS: ' + JSON.stringify(opts));
        await dimSelect.selectOption('artists.name');
    } else {
        console.log('NO_DIMENSION_SELECT: ' + await page.$eval('#outputControls', el => el.innerHTML.slice(0,1200)));
    }
    await page.waitForTimeout(500);
    await page.click('#getResults');
    await page.waitForTimeout(9000);
    const svg = await page.$$eval('#graphicsWrapper svg', s => s.length).catch(() => -1);
    const texts = await page.$$eval('#graphicsWrapper svg text', t => t.slice(0, 12).map(x => x.textContent)).catch(() => []);
    console.log('SVG_COUNT: ' + svg + ' TEXTS: ' + JSON.stringify(texts));
    console.log('SEARCHES: ' + JSON.stringify(net));
    await page.screenshot({ path: '/tmp/verify/spotify_barchart.png', fullPage: true });
    await browser.close();
})().catch(e => { console.error('VERIFY_FAILED', e.message); process.exit(1); });
EOF
cd /tmp/verify && node verify10.js 2>&1 | tail -12

